// buildInfoMeta returns the short commit hash and build timestamp embedded by
// the Go toolchain from VCS settings. Values are empty when unavailable (e.g.
// outside a git checkout or when -buildvcs=false).
func buildInfoMeta() (commit, buildTime string) {
	info, ok := debug.ReadBuildInfo()
	if !ok {
		return
	}
	for _, s := range info.Settings {
		switch s.Key {
		case "vcs.revision":
			if len(s.Value) > 8 {
				commit = s.Value[:8]
			} else {
				commit = s.Value
			}
		case "vcs.time":
			buildTime = s.Value
		}
	}
	return
}

