// vcsModified reports whether the binary was built from a dirty working tree,
// using the VCS metadata embedded by the Go toolchain at build time.
func vcsModified() bool {
	info, ok := debug.ReadBuildInfo()
	if !ok {
		return false
	}
	for _, s := range info.Settings {
		if s.Key == "vcs.modified" {
			return s.Value == "true"
		}
	}
	return false
}

func cmdVersion(args []string, w io.Writer) int {
	checkOnly := false
	jsonOutput := false
	for _, arg := range args {
		switch arg {
		case "--check-only", "-c":
			checkOnly = true
		case "--json":
			jsonOutput = true
		}
	}

	if jsonOutput {
		v := struct {
			Version string `json:"version"`
			Commit  string `json:"commit"`
			Dirty   bool   `json:"dirty"`
