// returns a non-empty commit when the test binary was built inside a git repo
// with embedded VCS metadata (the default for 'go test' runs).
func TestBuildInfoMetaNonemptyCommitInGitCheckout(t *testing.T) {
	commit, _ := buildInfoMeta()
	if commit == "" {
		t.Skip("no VCS commit embedded in test binary (built outside git repo or -buildvcs=false)")
	}
	for _, c := range commit {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			t.Errorf("buildInfoMeta commit %q contains non-hex character %c", commit, c)
		}
	}
}

